"""Derive a non-runtime six-faction readiness manifest from existing canonical data."""
from pathlib import Path
import json,hashlib,argparse
R=Path(__file__).resolve().parents[2];E=R/'Evidence/ProductionContinuation-20261008'
p=argparse.ArgumentParser();p.add_argument('--evidence-root',type=Path,required=True);p.add_argument('--matchup-receipt',type=Path,required=True);a=p.parse_args();E=a.evidence_root.resolve();assert E.is_relative_to((R/'Evidence').resolve())
proof=json.loads(a.matchup_receipt.read_text());assert proof['pass'] and proof['faction']=='orcs' and proof['unit']=='orc_hammer_warrior'
src=R/'Data/soul_campaign_start_states_v1_20260922.json';geo=R/'Data/soul_world_overmap_v1_20260922.json';s=json.loads(src.read_text())['scenarios']['six_faction_sandbox_candidate'];g=json.loads(geo.read_text());p=json.loads((R/'Data/CampaignComposition/presentation.json').read_text());ids={n['id'] for n in g['nodes']};edges={frozenset([e['a'],e['b']]) for e in g['edges']}
