out={'schema':2,'qualified_new_matchup_receipt':str(a.matchup_receipt.resolve().relative_to(R)),'qualified_new_matchup_receipt_sha256':hashlib.sha256(a.matchup_receipt.read_bytes()).hexdigest(),'status':'CONFIGURATION_GROUNDWORK_NOT_RUNTIME_SCENARIO','canonical_start_source':str(src.relative_to(R)),'canonical_start_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'geography_source':str(geo.relative_to(R)),'geography_sha256':hashlib.sha256(geo.read_bytes()).hexdigest(),'regions':36,'legal_pairs':51,'factions':rows,'owned_start_regions':len(s['region_owners']),'neutral_start_regions':len(s['neutral_regions']),'blockers':blockers,'new_gameplay_authority':False,'runtime_fixture_ownership_changed':False,'runtime_identity_gate':{'source':'Source/SoulCore/Private/SoulCampaignBattleBridge.cpp','player_faction':'humans','player_unit':'human_knight','ordered_enemy_pairs':[{'faction':'dwarves','unit':'dwarf_warrior','scope':'existing qualified bridge; inherited multi-role visual presentation remains unchanged'},{'faction':'orcs','unit':'orc_hammer_warrior','scope':'exact native hammer infantry, initial and reserves; cooked natural result, return and fresh load'}],'qualified_six_faction_roster_definitions':False},'configuration_contract':{'runtime_activation':False,'starting_forces':'BALANCE_LAB_OWNED_PENDING','diplomacy':'UNSET','required_roster_shape':{'total':7,'fighters':4,'ranged':1,'support_magic':1,'apex':1,'quadruped_body_plans':1,'heroes_separate':True},'shape_authority':'Source/SoulCore/Private/SoulFaction.cpp'},'implementation_sources':{n:hashlib.sha256((R/n).read_bytes()).hexdigest() for n in ['Source/SoulCore/Private/SoulCampaignBattleBridge.cpp','Source/SoulCore/Private/SoulFaction.cpp','Source/Soul/Private/SoulFounderPlaytestStateSubsystem.cpp']}}
